package practice;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;

/**
 * Turns the start time an operator types for a batch run, a local date-time in the data
 * centre's zone, into the moment the run is queued for.
 */
public class BatchStarts {

    /** The moment the job queue receives for a run the operator set for local in zone. */
    public static Instant queueAt(LocalDateTime local, ZoneId zone) {
        return startOf(local, zone).toInstant();
    }

    /** The start of the run as a ZonedDateTime in the data centre's zone. */
    static ZonedDateTime startOf(LocalDateTime local, ZoneId zone) {
        if (zone.getRules().getValidOffsets(local).isEmpty()) {
            throw new IllegalArgumentException(local + " does not happen in " + zone);
        }
        return ZonedDateTime.of(local, zone).withLaterOffsetAtOverlap();
    }
}

package practice;

import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            ZoneId berlin = ZoneId.of("Europe/Berlin");
            System.out.println("2027-07-15T22:00: " + BatchStarts.startOf(LocalDateTime.parse("2027-07-15T22:00"), berlin));
            System.out.println("2027-10-31T02:30 (happens twice): " + BatchStarts.startOf(LocalDateTime.parse("2027-10-31T02:30"), berlin));
            System.out.println("queued for 2027-10-31T02:30: " + BatchStarts.queueAt(LocalDateTime.parse("2027-10-31T02:30"), berlin));
            try {
                System.out.println("2027-03-28T02:30 (skipped): " + BatchStarts.startOf(LocalDateTime.parse("2027-03-28T02:30"), berlin));
            } catch (IllegalArgumentException refused) {
                System.out.println("2027-03-28T02:30 refused: " + refused.getMessage());
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

